insert into public.projects (slug, position, published, content) values
  ('objetivos', 0, true, '{"slug":"objetivos","frequency":"01.24","title":{"es":"Objetivos que sí se cumplen","en":"Goals that actually get done"},"client":"UBITS","year":"2024","accent":"64 96 255","mock":"dashboard","tagline":{"es":"Rediseño del módulo de objetivos para que líderes y colaboradores pasen de \"llenar un formato\" a conversar sobre avances reales.","en":"Redesign of the goals module so leaders and employees stop \"filling a form\" and start talking about real progress."},"role":{"es":"Lead UX/UI · investigación, diseño y sistema","en":"UX/UI Lead · research, design and system"},"team":{"es":"1 PM, 4 devs, 1 QA","en":"1 PM, 4 devs, 1 QA"},"duration":{"es":"5 meses","en":"5 months"},"tools":["Figma","Miro","Claude","Cursor","Hotjar"],"problem":{"context":{"es":"Las empresas configuraban objetivos al inicio del año y no volvían a abrirlos. El módulo era un formulario largo, sin seguimiento ni conexión con las conversaciones 1:1.","en":"Companies set goals at the start of the year and never opened them again. The module was a long form with no follow-up and no link to 1:1 conversations."},"quotes":[{"text":{"es":"“Los objetivos los lleno en enero y los vuelvo a ver en la evaluación.”","en":"“I fill in my goals in January and see them again at review time.”"},"who":{"es":"Colaborador, retail","en":"Employee, retail"}},{"text":{"es":"“No sé si mi equipo va bien hasta que ya es tarde.”","en":"“I don’t know if my team is on track until it’s too late.”"},"who":{"es":"Líder de área","en":"Team lead"}},{"text":{"es":"“Configurar un ciclo me toma una semana entera.”","en":"“Setting up a cycle takes me a whole week.”"},"who":{"es":"Admin de RR. HH.","en":"HR admin"}}],"stats":[{"value":"12%","label":{"es":"de objetivos con al menos un avance","en":"of goals with at least one update"}},{"value":"38 min","label":{"es":"para crear un objetivo","en":"to create one goal"}},{"value":"4/10","label":{"es":"satisfacción del admin","en":"admin satisfaction"}}]},"research":{"method":{"es":"14 entrevistas, 3 empresas, análisis de 9.000 objetivos y mapas de calor del flujo actual.","en":"14 interviews, 3 companies, analysis of 9,000 goals and heatmaps of the current flow."},"clusters":[{"title":{"es":"Olvido","en":"Forgetting"},"notes":[{"es":"Nadie recuerda volver","en":"Nobody remembers to come back"},{"es":"Sin recordatorios","en":"No reminders"},{"es":"Avance = evaluación","en":"Progress = review"}]},{"title":{"es":"Complejidad","en":"Complexity"},"notes":[{"es":"17 campos obligatorios","en":"17 required fields"},{"es":"Pesos confusos","en":"Confusing weights"},{"es":"Jerga de RR. HH.","en":"HR jargon"}]},{"title":{"es":"Visibilidad","en":"Visibility"},"notes":[{"es":"El líder no ve riesgo","en":"Leads can’t see risk"},{"es":"Sin vista de equipo","en":"No team view"}]}],"insights":[{"es":"El objetivo no es el formulario: es la conversación que provoca.","en":"The goal isn’t the form: it’s the conversation it sparks."},{"es":"Actualizar debe tomar menos que un mensaje de chat.","en":"Updating must take less time than a chat message."},{"es":"El líder necesita saber dónde intervenir, no ver todo.","en":"Leads need to know where to step in, not see everything."}]},"idea":{"hmw":{"es":"¿Cómo podríamos hacer que actualizar un objetivo sea tan natural como contar cómo vas?","en":"How might we make updating a goal as natural as saying how you’re doing?"},"principles":[{"title":{"es":"Un toque","en":"One tap"},"body":{"es":"Avance en un gesto, detalle solo si quieres.","en":"Progress in one gesture, detail only if you want."}},{"title":{"es":"Riesgo primero","en":"Risk first"},"body":{"es":"El líder ve primero lo que necesita atención.","en":"Leads see what needs attention first."}},{"title":{"es":"IA que redacta","en":"AI that drafts"},"body":{"es":"La IA propone objetivos SMART a partir de una idea.","en":"AI drafts SMART goals from a rough idea."}}]},"sketches":{"caption":{"es":"De 6 caminos explorados quedaron 2. El ganador puso el avance en la primera línea de cada tarjeta.","en":"Out of 6 explored paths, 2 survived. The winner put progress on the first line of every card."},"notes":[{"es":"avance arriba","en":"progress on top"},{"es":"¿semáforo?","en":"traffic light?"},{"es":"vista equipo","en":"team view"}]},"form":{"caption":{"es":"Arrastra para pasar del wireframe validado a la interfaz final con el sistema de diseño.","en":"Drag to go from the validated wireframe to the final UI built on the design system."}},"ai":{"intro":{"es":"La IA no reemplazó el criterio: comprimió semanas de exploración en días.","en":"AI didn’t replace judgment: it compressed weeks of exploration into days."},"steps":[{"tool":"Claude","prompt":{"es":"Agrupa estas 140 notas de entrevistas por necesidad, no por tema.","en":"Cluster these 140 interview notes by need, not by topic."},"output":{"es":"6 grupos + 3 tensiones entre líderes y colaboradores","en":"6 clusters + 3 tensions between leads and employees"}},{"tool":"Figma Make","prompt":{"es":"Genera 6 variaciones de tarjeta de objetivo con el avance como protagonista.","en":"Generate 6 goal-card variations with progress as the hero."},"output":{"es":"6 prototipos navegables en una tarde","en":"6 clickable prototypes in one afternoon"}},{"tool":"Cursor","prompt":{"es":"Construye el prototipo de \"check-in en un toque\" con datos reales anonimizados.","en":"Build the \"one-tap check-in\" prototype with real anonymized data."},"output":{"es":"Prototipo en código probado con 8 usuarios","en":"Coded prototype tested with 8 users"}}]},"results":{"metrics":[{"value":64,"suffix":"%","label":{"es":"objetivos con avance mensual","en":"goals with monthly updates"}},{"value":6,"suffix":" min","label":{"es":"para crear un objetivo","en":"to create a goal"}},{"value":3,"prefix":"×","suffix":"","label":{"es":"más check-ins de líderes","en":"more check-ins from leads"}}],"learnings":[{"es":"Medir la conversación, no el formulario.","en":"Measure the conversation, not the form."},{"es":"Prototipar en código cambió la calidad del feedback.","en":"Prototyping in code changed the quality of feedback."}]}}'::jsonb),
  ('barberlytics', 1, true, '{"slug":"barberlytics","frequency":"02.23","title":{"es":"Barberlytics","en":"Barberlytics"},"client":"Barberlytics","year":"2022 — 2025","accent":"232 140 48","mock":"mobile","tagline":{"es":"Una app para que la barbería deje de vivir en el WhatsApp del dueño: agenda, equipo, pagos y una IA que sugiere cómo llenar la silla vacía.","en":"An app so the barbershop stops living in the owner’s WhatsApp: schedule, staff, payments and an AI that suggests how to fill the empty chair."},"role":{"es":"Lead UX/UI · producto end-to-end","en":"UX/UI Lead · end-to-end product"},"team":{"es":"Fundadores, 3 devs","en":"Founders, 3 devs"},"duration":{"es":"3 años, entregas continuas","en":"3 years, continuous delivery"},"tools":["Figma","Claude","Cursor","n8n","Stripe"],"problem":{"context":{"es":"Las barberías gestionaban citas por chat y libreta. Las sillas vacías y los clientes que no llegaban eran pérdidas invisibles.","en":"Barbershops handled bookings through chat and notebooks. Empty chairs and no-shows were invisible losses."},"quotes":[{"text":{"es":"“Me paso el día contestando mensajes en vez de cortar.”","en":"“I spend the day answering messages instead of cutting hair.”"},"who":{"es":"Dueño de barbería","en":"Shop owner"}},{"text":{"es":"“Si alguien cancela, esa hora se pierde.”","en":"“If someone cancels, that hour is gone.”"},"who":{"es":"Barbero","en":"Barber"}}],"stats":[{"value":"22%","label":{"es":"citas perdidas por no-show","en":"appointments lost to no-shows"}},{"value":"2 h/día","label":{"es":"en mensajes de agenda","en":"spent on booking messages"}},{"value":"0","label":{"es":"datos para decidir","en":"data to make decisions"}}]},"research":{"method":{"es":"Observación en 6 barberías, shadowing de un día completo y entrevistas a clientes frecuentes.","en":"Observation in 6 barbershops, full-day shadowing and interviews with regular clients."},"clusters":[{"title":{"es":"Tiempo","en":"Time"},"notes":[{"es":"Chat todo el día","en":"Chatting all day"},{"es":"Doble reserva","en":"Double booking"},{"es":"Sin recordatorios","en":"No reminders"}]},{"title":{"es":"Dinero","en":"Money"},"notes":[{"es":"Pago en efectivo","en":"Cash only"},{"es":"Comisiones a mano","en":"Manual commissions"}]},{"title":{"es":"Relación","en":"Relationship"},"notes":[{"es":"Cliente fiel = barbero","en":"Loyal client = barber"},{"es":"Historial en la memoria","en":"History in memory"},{"es":"Fotos del corte","en":"Haircut photos"}]}],"insights":[{"es":"El cliente es fiel al barbero, no a la barbería.","en":"Clients are loyal to the barber, not the shop."},{"es":"La agenda es el corazón: todo lo demás cuelga de ella.","en":"The schedule is the heart: everything else hangs off it."}]},"idea":{"hmw":{"es":"¿Cómo podríamos llenar cada silla sin que el dueño toque el teléfono?","en":"How might we fill every chair without the owner touching the phone?"},"principles":[{"title":{"es":"Agenda viva","en":"Living schedule"},"body":{"es":"Huecos visibles y accionables al instante.","en":"Gaps visible and actionable instantly."}},{"title":{"es":"Reservar en 3 toques","en":"Book in 3 taps"},"body":{"es":"Barbero, servicio, hora. Nada más.","en":"Barber, service, time. Nothing else."}},{"title":{"es":"IA de negocio","en":"Business AI"},"body":{"es":"Sugiere promociones para las horas valle.","en":"Suggests promos for slow hours."}}]},"sketches":{"caption":{"es":"Bocetos en la barbería misma, probados con papel en la mano del cliente.","en":"Sketches made inside the shop, tested on paper in the client’s hand."},"notes":[{"es":"foto del barbero","en":"barber photo"},{"es":"3 toques","en":"3 taps"},{"es":"hueco = promo","en":"gap = promo"}]},"form":{"caption":{"es":"Del wireframe al producto: la reserva quedó en tres pasos.","en":"From wireframe to product: booking ended up in three steps."}},"ai":{"intro":{"es":"La IA vive dentro del producto, no solo en el proceso de diseño.","en":"AI lives inside the product, not just in the design process."},"steps":[{"tool":"Claude","prompt":{"es":"Con el historial de citas, detecta horas valle y propone una promoción por barbero.","en":"Using booking history, detect slow hours and propose a promo per barber."},"output":{"es":"Motor de sugerencias semanales","en":"Weekly suggestion engine"}},{"tool":"n8n","prompt":{"es":"Automatiza recordatorios 24 h y 2 h antes por WhatsApp.","en":"Automate WhatsApp reminders 24 h and 2 h before."},"output":{"es":"Flujo de recordatorios sin código","en":"No-code reminder flow"}},{"tool":"Cursor","prompt":{"es":"Prototipo del flujo de reserva con datos de una barbería real.","en":"Booking flow prototype with a real shop’s data."},"output":{"es":"Validado con 20 clientes","en":"Validated with 20 clients"}}]},"results":{"metrics":[{"value":41,"prefix":"−","suffix":"%","label":{"es":"no-shows","en":"no-shows"}},{"value":18,"prefix":"+","suffix":"%","label":{"es":"ocupación de sillas","en":"chair occupancy"}},{"value":90,"suffix":" s","label":{"es":"para reservar","en":"to book"}}],"learnings":[{"es":"Diseñar en el lugar donde ocurre el problema.","en":"Design where the problem happens."},{"es":"La IA más útil es la que no se nota.","en":"The most useful AI is the one you don’t notice."}]}}'::jsonb),
  ('carga-masiva-ia', 2, true, '{"slug":"carga-masiva-ia","frequency":"03.26","title":{"es":"Carga masiva con IA","en":"AI bulk import"},"client":"UBITS","year":"2026","accent":"38 178 120","mock":"upload","tagline":{"es":"Una herramienta que entiende el Excel desordenado del cliente y lo convierte en datos listos, en vez de pedirle que lo arregle.","en":"A tool that understands the client’s messy spreadsheet and turns it into clean data, instead of asking them to fix it."},"role":{"es":"Diseño y construcción · de la idea al código","en":"Design and build · from idea to code"},"team":{"es":"Yo + 1 dev backend","en":"Me + 1 backend dev"},"duration":{"es":"6 semanas","en":"6 weeks"},"tools":["Claude Code","Cursor","Figma","n8n"],"problem":{"context":{"es":"Subir datos históricos exigía una plantilla rígida. El 70% de los archivos fallaban y soporte terminaba haciéndolo a mano.","en":"Uploading historical data required a rigid template. 70% of files failed and support ended up doing it by hand."},"quotes":[{"text":{"es":"“Me dice ‘error en la fila 312’ y no sé qué significa.”","en":"“It says ‘error in row 312’ and I don’t know what it means.”"},"who":{"es":"Admin de cliente","en":"Client admin"}},{"text":{"es":"“Cada carga es un ticket para nosotros.”","en":"“Every upload becomes a ticket for us.”"},"who":{"es":"Equipo de soporte","en":"Support team"}}],"stats":[{"value":"70%","label":{"es":"archivos rechazados","en":"files rejected"}},{"value":"3 días","label":{"es":"promedio por carga","en":"average per import"}},{"value":"120","label":{"es":"tickets al mes","en":"tickets per month"}}]},"research":{"method":{"es":"Análisis de 300 archivos reales fallidos y 8 sesiones con admins mientras subían datos.","en":"Analysis of 300 real failed files and 8 sessions with admins while uploading data."},"clusters":[{"title":{"es":"Formato","en":"Format"},"notes":[{"es":"Columnas con otro nombre","en":"Columns named differently"},{"es":"Fechas en 5 formatos","en":"Dates in 5 formats"}]},{"title":{"es":"Confianza","en":"Trust"},"notes":[{"es":"¿Se subió bien?","en":"Did it upload right?"},{"es":"Miedo a duplicar","en":"Fear of duplicates"},{"es":"Errores crípticos","en":"Cryptic errors"}]}],"insights":[{"es":"El usuario no debe adaptarse al sistema: el sistema debe leer al usuario.","en":"Users shouldn’t adapt to the system: the system should read the user."},{"es":"La confianza viene de ver el resultado antes de confirmar.","en":"Trust comes from seeing the result before confirming."}]},"idea":{"hmw":{"es":"¿Cómo podríamos aceptar cualquier archivo y explicar cada cambio en lenguaje humano?","en":"How might we accept any file and explain every change in plain language?"},"principles":[{"title":{"es":"Cualquier archivo","en":"Any file"},"body":{"es":"La IA mapea columnas y formatos.","en":"AI maps columns and formats."}},{"title":{"es":"Vista previa","en":"Preview"},"body":{"es":"Ves los datos limpios antes de confirmar.","en":"See clean data before confirming."}},{"title":{"es":"Errores que ayudan","en":"Helpful errors"},"body":{"es":"Cada problema trae su solución sugerida.","en":"Every issue comes with a suggested fix."}}]},"sketches":{"caption":{"es":"El boceto clave: una sola pantalla con el archivo a la izquierda y la interpretación de la IA a la derecha.","en":"The key sketch: one screen with the file on the left and the AI’s reading on the right."},"notes":[{"es":"antes / después","en":"before / after"},{"es":"confianza %","en":"confidence %"},{"es":"arreglar en línea","en":"inline fix"}]},"form":{"caption":{"es":"Diseñado y construido por mí: el wireframe se convirtió directamente en código.","en":"Designed and built by me: the wireframe turned straight into code."}},"ai":{"intro":{"es":"Aquí la IA fue material de diseño y también de construcción.","en":"Here AI was both design material and building material."},"steps":[{"tool":"Claude","prompt":{"es":"Clasifica estos 300 archivos fallidos por tipo de error.","en":"Classify these 300 failed files by error type."},"output":{"es":"9 patrones que cubren el 94% de fallos","en":"9 patterns covering 94% of failures"}},{"tool":"Claude Code","prompt":{"es":"Implementa el mapeo de columnas con nivel de confianza y explicación.","en":"Implement column mapping with confidence level and explanation."},"output":{"es":"Motor de mapeo en producción","en":"Mapping engine in production"}},{"tool":"Figma","prompt":{"es":"Sistema de estados: leyendo, dudoso, corregido, listo.","en":"State system: reading, uncertain, fixed, ready."},"output":{"es":"4 estados en el sistema de diseño","en":"4 states in the design system"}}]},"results":{"metrics":[{"value":92,"suffix":"%","label":{"es":"archivos aceptados","en":"files accepted"}},{"value":8,"suffix":" min","label":{"es":"promedio por carga","en":"average per import"}},{"value":85,"prefix":"−","suffix":"%","label":{"es":"tickets de soporte","en":"support tickets"}}],"learnings":[{"es":"Construir yo mismo eliminó la pérdida entre diseño y desarrollo.","en":"Building it myself removed the loss between design and dev."},{"es":"Explicar la IA es parte de la interfaz.","en":"Explaining the AI is part of the interface."}]}}'::jsonb),
  ('nomina', 3, true, '{"slug":"nomina","frequency":"04.19","title":{"es":"Nómina sin fricción","en":"Frictionless payroll"},"client":"Siigo","year":"2019","accent":"214 64 72","mock":"table","tagline":{"es":"Liquidar la nómina de una pyme pasó de un día de hojas de cálculo a un flujo guiado con validaciones antes del error.","en":"Running payroll for a small business went from a day of spreadsheets to a guided flow that validates before the mistake."},"role":{"es":"Senior UX/UI · flujo y componentes","en":"Senior UX/UI · flow and components"},"team":{"es":"2 diseñadores, 6 devs","en":"2 designers, 6 devs"},"duration":{"es":"4 meses","en":"4 months"},"tools":["Sketch","Figma","Miro","Maze"],"problem":{"context":{"es":"Contadores liquidaban nómina saltando entre pantallas y Excel. Un error se descubría cuando el empleado reclamaba.","en":"Accountants ran payroll jumping between screens and Excel. Mistakes were found when the employee complained."},"quotes":[{"text":{"es":"“Reviso todo dos veces porque no confío en el sistema.”","en":"“I check everything twice because I don’t trust the system.”"},"who":{"es":"Contadora independiente","en":"Freelance accountant"}},{"text":{"es":"“Las novedades me llegan por correo y las paso a mano.”","en":"“Changes reach me by email and I enter them by hand.”"},"who":{"es":"Auxiliar contable","en":"Accounting assistant"}}],"stats":[{"value":"7 h","label":{"es":"por liquidación","en":"per payroll run"}},{"value":"1 de 5","label":{"es":"nóminas con corrección","en":"payrolls needing a fix"}}]},"research":{"method":{"es":"Indagación contextual con 10 contadores y pruebas de usabilidad del flujo existente.","en":"Contextual inquiry with 10 accountants and usability tests of the existing flow."},"clusters":[{"title":{"es":"Novedades","en":"Changes"},"notes":[{"es":"Llegan por correo","en":"Arrive by email"},{"es":"Horas extra a mano","en":"Manual overtime"}]},{"title":{"es":"Confianza","en":"Trust"},"notes":[{"es":"Doble revisión","en":"Double check"},{"es":"Totales ocultos","en":"Hidden totals"},{"es":"Miedo a la DIAN","en":"Fear of the tax office"}]}],"insights":[{"es":"El contador necesita ver el impacto de cada cambio en el total.","en":"Accountants need to see each change’s impact on the total."},{"es":"Validar antes es más barato que corregir después.","en":"Validating early is cheaper than fixing later."}]},"idea":{"hmw":{"es":"¿Cómo podríamos hacer que el contador confíe en el total sin revisar dos veces?","en":"How might we make accountants trust the total without double-checking?"},"principles":[{"title":{"es":"Total siempre visible","en":"Total always visible"},"body":{"es":"Cada cambio muestra su efecto.","en":"Every change shows its effect."}},{"title":{"es":"Pasos claros","en":"Clear steps"},"body":{"es":"Novedades, revisión, aprobación.","en":"Changes, review, approval."}}]},"sketches":{"caption":{"es":"Explorando cómo mostrar el total \"vivo\" mientras se editan novedades.","en":"Exploring how to show a \"live\" total while editing changes."},"notes":[{"es":"total fijo","en":"sticky total"},{"es":"alerta antes","en":"warn early"},{"es":"por empleado","en":"per employee"}]},"form":{"caption":{"es":"La tabla final: edición en línea y total que reacciona al instante.","en":"The final table: inline editing and a total that reacts instantly."}},"ai":{"intro":{"es":"En 2019 la IA aún no era parte del proceso; hoy la aplicaría así:","en":"In 2019 AI wasn’t part of the process yet; today I would apply it like this:"},"steps":[{"tool":"Claude","prompt":{"es":"Lee los correos de novedades y conviértelos en registros de nómina.","en":"Read the change emails and turn them into payroll records."},"output":{"es":"Novedades precargadas para revisar","en":"Pre-filled changes to review"}},{"tool":"Claude","prompt":{"es":"Detecta valores atípicos frente a los últimos 6 meses.","en":"Flag outliers against the last 6 months."},"output":{"es":"Alertas antes de aprobar","en":"Warnings before approval"}}]},"results":{"metrics":[{"value":65,"prefix":"−","suffix":"%","label":{"es":"tiempo de liquidación","en":"payroll time"}},{"value":70,"prefix":"−","suffix":"%","label":{"es":"correcciones","en":"corrections"}}],"learnings":[{"es":"La confianza es una métrica de diseño.","en":"Trust is a design metric."}]}}'::jsonb)
